+  background: color-mix(in oklab, var(--surface) 78%, transparent);
+}
+.diagram .node h4{margin:0 0 6px; font-size:1rem}
+.diagram .node p{margin:0; color:var(--muted); font-size:.93rem}
+
+.diagram-ecosystem{display:grid; grid-template-columns: 1fr 70px 1fr 70px 1fr; gap:10px; align-items:stretch}
