+
+.carousel{position:relative; overflow:hidden}
+.track{display:flex; transition: transform var(--transition); will-change: transform}
+.slide{min-width:100%; padding:0}
+.quote{padding:18px; border-radius: 16px; border:1px solid color-mix(in oklab, var(--border) 65%, transparent); background: color-mix(in oklab, var(--surface) 80%, transparent)}
+.quote p{margin:0 0 10px; color:var(--text)}
+.quote span{color:var(--muted)}
+.dots{display:flex; gap:8px; justify-content:center; margin-top:12px}
