+.dotbtn[aria-selected="true"]{background: var(--brand); border-color: color-mix(in oklab, var(--brand) 70%, white)}
+.dotbtn:focus-visible{outline:none; box-shadow: var(--ring)}
+
+.form{display:grid; gap:12px}
+.field{display:grid; gap:6px}
+.field label{color:var(--muted); font-weight:700; font-size:.92rem}
+.field input, .field select, .field textarea{
+  width:100%;
+  background: color-mix(in oklab, var(--surface) 80%, transparent);
+  border:1px solid color-mix(in oklab, var(--border) 65%, transparent);
+  color: var(--text);
+  border-radius: 14px;
+  padding:12px 12px;
+  font:inherit;
+  transition: box-shadow var(--transition), border-color var(--transition), background var(--transition);
+}
+.field textarea{min-height:110px; resize:vertical}
+.field input:focus, .field select:focus, .field textarea:focus{outline:none; box-shadow: var(--ring); border-color: color-mix(in oklab, var(--brand) 55%, var(--border))}
+.hint{color:var(--muted-2); font-size:.9rem}
+.error{color: color-mix(in oklab, var(--danger) 85%, white); font-size:.9rem; display:none}
+.field[data-invalid="true"] .error{display:block}
+.field[data-invalid="true"] input,
+.field[data-invalid="true"] select,
+.field[data-invalid="true"] textarea{border-color: color-mix(in oklab, var(--danger) 70%, var(--border))}
+
+.footer{padding: 42px 0; border-top:1px solid color-mix(in oklab, var(--border) 55%, transparent); background: color-mix(in oklab, var(--bg-1) 70%, transparent)}
+.footer-grid{display:grid; grid-template-columns: 1.2fr repeat(4, minmax(0, 1fr)); gap: var(--grid-gap)}
+.footer h4{margin:0 0 10px; font-size:1rem}
+.footer a{color:var(--muted)}
+.footer a:hover{color:var(--text); text-decoration:none}
+.footer small{color:var(--muted-2)}
+@media (max-width: 920px){.footer-grid{grid-template-columns:1fr 1fr}}
+@media (max-width: 640px){.footer-grid{grid-template-columns:1fr}}
+
+.toast{
+  position:fixed;
+  left:50%; bottom:18px; transform:translateX(-50%);
+  background: color-mix(in oklab, var(--surface-2) 90%, transparent);
+  border:1px solid color-mix(in oklab, var(--border) 70%, transparent);
+  padding:10px 12px; border-radius: 999px;
+  box-shadow: var(--shadow);
+  color: var(--text);
+  display:none;
+}
+.toast.show{display:block}
+
+.cookie{
+  position:fixed; left:18px; right:18px; bottom:18px;
+  max-width: 980px; margin:0 auto;
+  border-radius: 18px;
+  padding:14px;
+  border:1px solid color-mix(in oklab, var(--border) 65%, transparent);
+  background: linear-gradient(180deg, color-mix(in oklab, var(--surface-2) 92%, transparent), color-mix(in oklab, var(--surface) 92%, transparent));
+  box-shadow: var(--shadow);
+  display:none;
+}
+.cookie.show{display:block}
+.cookie-inner{display:flex; gap:12px; align-items:flex-start; justify-content:space-between}
+.cookie p{margin:4px 0 0; color:var(--muted); font-size:.95rem}
+@media (max-width: 640px){
+  .cookie-inner{flex-direction:column}
+  .cookie-actions{display:flex; gap:10px; width:100%}
+  .cookie-actions .btn{flex:1}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{transition:none !important; scroll-behavior:auto !important}
+}
+
